'use strict';
const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = name => '<i>'+ (ICONS[name] || ICONS.Circle) +'</i>';
const DAY = 86400000;
const TODAY = '2026-10-29';
const todayTime = Date.parse(TODAY+'T20:00:00+08:00');
const age = date => Math.max(0,(todayTime-Date.parse(date+'T20:00:00+08:00'))/DAY);
const datePlus = days => new Date(todayTime+days*DAY+8*3600000).toISOString().slice(0,10);
const shortDate = date => date.slice(5).replace('-','/');
const activeStatus = q => ['open','verify'].includes(q.status);
const labels = {open:'复习中',verify:'待验证',closed:'已掌握',paused:'已暂停'};
