let questions = structuredClone(INITIAL);
let view = 'today',grade='7',parent=false,budget=15,subject='全部',statusFilter='active',tagFilter='全部',search='',sort='recommended';
let modal=null,session=null,localImage=null,uploadFile=null,uploadScenario='clear',lastFocus=null,toastTimer;
const profiles = () => questions.filter(q=>q.grade===grade);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function statusBadge(q){return '<span class="tag '+({open:'',verify:'amber',closed:'green',paused:''}[q.status])+'">'+(q.status==='closed'?icon('CheckCheck'):'')+labels[q.status]+'</span>';}
function tags(q){return '<span class="tag rust">'+esc(q.subject)+' · '+esc(q.topic)+'</span>'+q.tags.map(t=>'<span class="tag">'+esc(t)+'</span>').join('');}
function score(q){const overdue=Math.max(0,age(q.due));const retrievalRisk=1-Math.exp(-age(q.last)/q.stability);return 35*Math.min(overdue/5,1)+25*retrievalRisk+20*Math.min(q.lapses/3,1)+(q.status==='verify'?15:0)+(q.tags.includes('期中重点')?8:0)+Math.min(age(q.created),20)/4;}
function reason(q){if(q.due>TODAY)return '还未到期 · '+shortDate(q.due)+' 再练更合适，也可提前练习';if(q.status==='verify')return '距独立做对已 '+age(q.last)+' 天 · 今天完成最后的延迟验证';if(q.lapses>=2)return '相似错误出现 '+q.lapses+' 次 · '+(q.due<TODAY?'已到期 '+age(q.due)+' 天':'今天适合再独立试试');if(!q.attempts.length)return '刚收录的新错题 · 先试一次独立订正';return '上次复习距今 '+age(q.last)+' 天 · 到期巩固，检查能否独立完成';}
function candidates(dueOnly=true){return profiles().filter(q=>activeStatus(q)&&(subject==='全部'||q.subject===subject)&&(!dueOnly||q.due<=TODAY)).sort((a,b)=>score(b)-score(a));}
function plan(){const source=candidates(true);const picked=[];let total=0;for(const q of source){if(total+q.minutes<=budget){picked.push(q);total+=q.minutes;}}return {items:picked,total};}
function evidence(q){
 if(q.status==='closed'&&q.closureEvidence)return q.closureEvidence;
 const events=q.attempts.filter(a=>a.confirmed).slice().sort((a,b)=>a.date.localeCompare(b.date));
 const lastFailure=events.findLastIndex(a=>!a.correct&&!a.newSkill);
 const valid=events.slice(lastFailure+1).filter(a=>a.correct&&a.independent&&!a.newSkill);
 const base=valid.filter(a=>a.type==='original'||a.type==='spotcheck');
 const days=[...new Set(base.map(a=>a.date))].sort();
 const spaced=days.length>=2&&Date.parse(days[days.length-1])-Date.parse(days[days.length-2])>=DAY;
 const lastBase=base.at(-1),lastBaseIndex=valid.lastIndexOf(lastBase),priorSuccess=valid[lastBaseIndex-1];
 const delayed=!!(spaced&&priorSuccess&&lastBaseIndex===valid.length-1&&Date.parse(lastBase.date)-Date.parse(priorSuccess.date)>=7*DAY);
 const transfer=valid.some(a=>['similar','advanced'].includes(a.type));
 return {spaced,delayed,transfer,ready:spaced&&delayed&&transfer,days,valid};
}
function rules(q){const e=evidence(q);return '<div class="rule-list">'+[[e.spaced,'至少两次跨天、独立完成原题或抽检'],[e.transfer,'独立通过一道同技能的新变式'],[e.delayed,'最后一次独立验证，间隔至少 7 天']].map(([done,text])=>'<div class="rule-line '+(done?'done':'')+'">'+icon(done?'CircleCheck':'Circle')+'<span>'+text+'</span></div>').join('')+'</div>';}
function metrics(){const p=profiles();const due=p.filter(q=>activeStatus(q)&&q.due<=TODAY).length;const closed=p.filter(q=>q.status==='closed').length;const verify=p.filter(q=>q.status==='verify').length;const open=p.filter(activeStatus).length;return '<div class="stats">'+[[due,'道','今天适合复习','按历史表现安排'],[verify,'道','正在等待验证','再给掌握一点时间'],[closed,'道','已验证掌握','退出日常复习队列'],[open,'道','仍在学习路上','一步一步，慢慢减少']].map(([n,u,label,note])=>'<div class="stat"><div class="stat-value">'+n+'<em>'+u+'</em></div><div class="stat-label">'+label+'</div><div class="stat-note">'+note+'</div></div>').join('')+'</div>';}
function heading(title,sub,action='',eyebrow='YOUR LEARNING, GROWING'){return '<div class="page-heading"><div><div class="eyebrow">'+eyebrow+'</div><h1>'+title+'</h1><p>'+sub+'</p></div>'+action+'</div>';}
function parentNotice(){if(!parent)return '';return '<div class="parent-summary">'+icon('GraduationCap')+' '+(grade==='5'?'小学阶段：家长协助拍照、核对识别与主观题过程；请让孩子自己先作答。':'初中阶段：孩子自主订正和复习，家长关注反复错因与时间负担。')+'<br>本页只展示该孩子的演示记录；查看解析和家长代答不能作为独立掌握证据。</div>';}
function subjectChips(){return '<div class="chips">'+['全部',...new Set(profiles().filter(activeStatus).map(q=>q.subject))].map(s=>'<button class="chip '+(subject===s?'active':'')+'" data-subject="'+esc(s)+'" aria-pressed="'+(subject===s)+'">'+esc(s)+'</button>').join('')+'</div>';}
function questionRows(items){return items.map((q,i)=>'<article class="question-row"><span class="question-number">'+String(i+1).padStart(2,'0')+'</span><div><button class="question-title" data-detail="'+q.id+'">'+esc(q.title)+'</button><div class="question-meta">'+tags(q)+statusBadge(q)+'</div><p class="reason">'+icon('Clock')+esc(reason(q))+'</p></div><div class="q-action"><span class="q-time">约 '+q.minutes+' 分钟</span><button class="circle-btn" data-practice="'+q.id+'" aria-label="练习'+esc(q.title)+'">'+icon('ArrowRight')+'</button></div></article>').join('');}
function todayView(){const p=plan();return heading('今天，把这几道题学扎实。','不用把所有错题重做一遍。先练最需要找回的，再验证快要学会的。','<button class="btn" data-go="inbox">'+icon('Camera')+'微信拍照收题</button>','A LITTLE PROGRESS, EVERY DAY')+parentNotice()+metrics()+'<div class="workspace"><section><div class="plan-head"><div class="row between"><div><h2>为你安排的 '+budget+' 分钟</h2><p>'+p.items.length+' 道题 · 预计 '+p.total+' 分钟 · '+(grade==='5'?'先自己试，家长再帮忙核对':'穿插不同知识点，练习自己判断方法')+'</p></div><div class="budget" aria-label="每日复习时间">'+[10,15,20].map(n=>'<button data-budget="'+n+'" class="'+(budget===n?'active':'')+'" aria-pressed="'+(budget===n)+'">'+n+' 分钟</button>').join('')+'</div></div><div class="row between" style="margin-top:18px"><span class="small-text muted">题目可少一点，独立思考多一点。</span><button class="btn primary" id="start-plan" '+(!p.items.length?'disabled':'')+'>开始这组复习 '+icon('ArrowRight')+'</button></div></div><div class="section-title"><h2>先练这些，刚刚好</h2><a class="text-btn" href="#library">按标签找题 '+icon('ArrowUpRight')+'</a></div>'+subjectChips()+(p.items.length?questionRows(p.items):'<div class="empty"><h3>这一科今天没有到期题目</h3><p>可以休息一下，也可以按需找题提前练习。</p><a class="btn small" href="#library">去错题库找题</a></div>')+'<div class="list-foot">'+icon('ShieldCheck')+'已掌握和已暂停的题目，不进入日常推荐。</div></section><aside class="right-stack"><section class="panel panel-pad"><div class="row between"><h2 class="small-heading">为什么是今天？</h2>'+icon('History')+'</div><canvas id="retention-chart" class="line-chart" aria-label="示意图：记忆随时间衰减，间隔复习后保持更久" role="img"></canvas><div class="legend"><span><b></b>间隔后再复习</span><span><b></b>一直没有复习</span></div><p class="aside-note">结合上次复习、独立作答和反复错因，找到适合再试一次的时间。</p><div class="aside-highlight">今天推荐「'+esc(p.items[0]?.topic||'按需练习')+'」<br>'+esc(p.items[0]?reason(p.items[0]):'目前无需追赶复习任务。')+'</div><p class="mini-rule">曲线仅作原理示意，不表示孩子的真实记忆概率。</p></section><section class="panel panel-pad"><div class="row between"><h2 class="small-heading">从做对，到真正掌握</h2><span class="tag green">看见进步</span></div>'+[[true,'先把错因想明白','订正与看解析，是学习的开始'],[true,'隔一段时间，自己做对','同一天重复刷，不累加掌握次数'],[false,'换道同类题，也会做','验证方法能否迁移'],[false,'延迟验证后，放下这道题','达标后进入掌握档案']].map(([done,t,d])=>'<div class="progress-item"><span class="step-icon '+(done?'done':'')+'">'+icon(done?'Check':'Circle')+'</span><div><strong>'+t+'</strong><p>'+d+'</p></div></div>').join('')+'<div class="inset-footer">这是学习路径说明；每道题的实际证据见详情。</div></section></aside></div>';}
function libraryItems(){let list=profiles().filter(q=>(statusFilter==='active'?activeStatus(q):statusFilter==='all'||q.status===statusFilter)&&(subject==='全部'||q.subject===subject)&&(tagFilter==='全部'||q.tags.includes(tagFilter)||q.topic===tagFilter));const tokens=search.toLowerCase().trim().split(/\s+/).filter(Boolean);list=list.filter(q=>tokens.every(t=>[q.title,q.topic,q.stem,q.subject,q.source||'',q.additionalSources?.length?'微信 小知':'',...q.tags].join(' ').toLowerCase().includes(t)));return list.sort((a,b)=>sort==='recent'?b.created.localeCompare(a.created):sort==='due'?a.due.localeCompare(b.due):score(b)-score(a));}
function libraryView(){const p=profiles();return heading('把每一道错题，整理成线索。','按知识点、错因和学习进度找题。默认只看还在学习中的错题。','<button class="btn primary" data-go="inbox">'+icon('Plus')+'收录错题</button>')+parentNotice()+subjectChips()+'<div class="toolbar"><label class="search">'+icon('Search')+'<input id="search" aria-label="搜索错题" placeholder="试试：数学 移项变号 / 分数 / 漏看条件" value="'+esc(search)+'"></label><select class="select" id="tag-filter" aria-label="按标签筛选"><option value="全部">全部知识点与错因</option>'+[...new Set(p.flatMap(q=>[q.topic,...q.tags]))].map(t=>'<option '+(tagFilter===t?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select><select class="select" id="sort" aria-label="题目排序"><option value="recommended" '+(sort==='recommended'?'selected':'')+'>适合复习优先</option><option value="due" '+(sort==='due'?'selected':'')+'>最早到期优先</option><option value="recent" '+(sort==='recent'?'selected':'')+'>最近收录优先</option></select></div><nav class="status-tabs" aria-label="学习状态">'+[['active','未掌握',p.filter(activeStatus).length],['verify','待验证',p.filter(q=>q.status==='verify').length],['closed','已掌握',p.filter(q=>q.status==='closed').length],['paused','已暂停',p.filter(q=>q.status==='paused').length],['all','全部',p.length]].map(([v,t,n])=>'<button data-status="'+v+'" class="'+(statusFilter===v?'active':'')+'" aria-pressed="'+(statusFilter===v)+'">'+t+'<span>'+n+'</span></button>').join('')+'</nav><div id="library-results"></div>';}
function drawLibraryResults(){const list=libraryItems();$('#library-results').innerHTML='<div class="row between result-caption"><span>找到 '+list.length+' 道题'+(search?' · 关键词筛选':'')+' · '+(statusFilter==='active'?'已排除已掌握与暂停题':'按所选状态显示')+'</span>'+(list.some(activeStatus)?'<button class="text-btn" id="practice-results">复习当前结果 '+icon('ArrowRight')+'</button>':'')+'</div>'+ (list.length?list.map(q=>'<article class="library-card"><div class="card-top"><span class="small-text muted">'+q.subject+' · '+(q.grade==='7'?'七':'五')+'年级 · '+shortDate(q.created)+' 收录</span>'+statusBadge(q)+'</div>'+wxSourceLine(q)+'<h3><button class="question-title" data-detail="'+q.id+'">'+esc(q.title)+'</button></h3><div class="question-meta">'+tags(q)+'</div><div class="card-stem">'+esc(q.stem)+'</div><p class="reason">'+icon('History')+esc(q.status==='closed'?'跨天、变式与延迟验证均已通过 · '+shortDate(q.closedAt)+' 进入掌握档案':q.status==='paused'?'已暂停，恢复前不会出现在日常复习里':reason(q))+'</p><div class="card-bottom"><span>复习记录 '+q.attempts.length+' 次 · '+(q.status==='closed'?'后续低频抽检':'建议 '+shortDate(q.due)+' 再练')+'</span><div class="row"><button class="text-btn" data-detail="'+q.id+'">详情与标签</button>'+(activeStatus(q)?'<button class="text-btn" data-variant="'+q.id+'">举一反三</button><button class="text-btn" data-practice="'+q.id+'">'+(q.due>TODAY?'提前练习':'独立试一题')+' '+icon('ArrowRight')+'</button>':'')+'</div></div></article>').join(''):'<div class="empty">'+icon('Search')+'<h3>没有找到符合条件的题目</h3><p>可以少用一个关键词，或者换一组标签。</p><button class="btn small" id="clear-filters">清除筛选</button></div>');}
function localInboxView(){return '<div class="intake-layout"><section><div class="upload-zone">'+icon('Camera')+'<h2>拍照或从相册选题</h2><p>原图先保留，识别不完整也不会丢失。</p><div class="row" style="justify-content:center"><button class="btn primary" id="choose-photo">'+icon('Upload')+'选择本地照片</button><button class="btn" id="sample-photo">用示例体验</button></div><input type="file" id="photo-file" accept="image/png,image/jpeg,image/webp" hidden><div id="photo-preview">'+(localImage?'<img class="local-image" src="'+localImage+'" alt="所选错题照片的本地预览">':'')+'</div><p style="margin-bottom:0">静态演示：照片仅本机预览，识别结果为预设题干。</p></div><div id="intake-form"></div></section><aside class="panel panel-pad"><h2>少做整理，多做思考。</h2>'+[['1','先留住原图','拍糊了可补拍；重复照片提示合并，保留原有复习历史。'],['2','识别建议，你来核对','拆分题目、判断科目和知识点。模糊题干与低置信度结果先待确认。'],['3','一个错因，就够开始','知识点与年级自动建议，错因由孩子确认，后续可以修改。'],['4','加入复习，等合适的时机','入库代表值得再学一次。看懂解析还不能标为已掌握。']].map(([n,t,d])=>'<div class="milestone"><span class="n">'+n+'</span><div><h3>'+t+'</h3><p>'+d+'</p></div></div>').join('')+'<div class="callout">'+(grade==='5'?'小学阶段，家长可以帮忙核对识别；题目仍由孩子自己先尝试。':'初中阶段，孩子自主整理；家长只需关注反复错因与复习负担。')+'</div><div class="chips"><button class="chip" data-intake-scenario="clear">清晰单题</button><button class="chip" data-intake-scenario="blur">模糊题目</button><button class="chip" data-intake-scenario="duplicate">重复照片</button></div></aside></div>';}
function intakeForm(){if(uploadScenario==='blur'){$('#intake-form').innerHTML='<div class="panel panel-pad"><span class="tag amber">原图已保留 · 待补拍</span><h2 style="margin-top:12px">这道题有些看不清</h2><p class="aside-note" style="margin:12px 0">题干缺失时暂不进入复习，也不猜测题目内容。实际产品保留原图供补拍和人工核对。</p><button class="btn" data-intake-scenario="clear">模拟清晰补拍</button></div>';return;}if(uploadScenario==='duplicate'){$('#intake-form').innerHTML='<div class="panel panel-pad"><span class="tag amber">发现相似原图</span><h2 style="margin-top:12px">这道题，好像已经收录了</h2><p class="aside-note" style="margin:12px 0">合并后追加来源，不重建错题，也不清空复习记录。</p><button class="btn primary" id="merge-duplicate">合并到已有错题</button></div>';return;}$('#intake-form').innerHTML='<section class="panel"><div class="panel-head"><div><h2>核对这道题</h2><p>预设识别示例 · 可编辑 · 尚未进入复习</p></div><span class="tag amber">待确认</span></div><div class="panel-pad"><div class="form-two"><label class="field">科目<select id="intake-subject"><option>数学</option><option>英语</option><option>语文</option></select></label><label class="field">知识点<input id="intake-topic" value="'+(grade==='5'?'异分母分数加法':'一元一次方程')+'"></label></div><label class="field">题干<textarea id="intake-stem">'+(grade==='5'?'计算：1/3 + 1/6 = ?（请用分数填写）':'解方程：2x + 3 = 11，x = ?')+'</textarea></label><label class="field">我的错因（可修改）<input id="intake-tags" value="'+(grade==='5'?'忘记通分, 计算':'移项变号, 概念')+'" placeholder="用逗号隔开，比如：漏看条件, 计算"></label><label class="checks"><input type="checkbox" id="intake-confirm"><span>我已核对题干、科目与知识点<br><span class="muted small-text">小学可由家长协助核对，加入后仍需孩子独立作答。</span></span></label><div class="row between"><span class="small-text muted">原图与上传时间随记录保留</span><button class="btn primary" id="add-intake">确认并加入复习 '+icon('ArrowRight')+'</button></div></div></section>';}
function masteryView(){const closed=profiles().filter(q=>q.status==='closed'),verify=profiles().filter(q=>q.status==='verify');return heading('学会的证据，替你认真记着。','已掌握的错题退出日常复习。偶尔抽检，发现同类问题再打开。','','PROGRESS YOU CAN TRUST')+parentNotice()+metrics()+'<div class="workspace"><section><div class="section-title"><h2>已验证掌握</h2><span>'+closed.length+' 道</span></div>'+(closed.length?closed.map(q=>'<article class="closed-card"><div class="row between"><span class="tag green">'+icon('ShieldCheck')+'已掌握</span><span class="small-text muted">'+shortDate(q.closedAt)+' 验证完成</span></div><h2>'+esc(q.title)+'</h2><div class="question-meta">'+tags(q)+'</div>'+rules(q)+'<div class="card-bottom"><span>下次低频抽检 · '+shortDate(q.due)+'</span><div class="row"><button class="text-btn" data-detail="'+q.id+'">查看学习轨迹</button><button class="text-btn" data-spotcheck="'+q.id+'">现在抽检 '+icon('ArrowRight')+'</button></div></div></article>').join(''):'<div class="empty"><h3>第一道真正学会的错题，值得期待</h3><p>完成跨天复习、变式与延迟验证后，就会出现在这里。</p></div>')+'<div class="section-title"><h2>再验证一步</h2><span>'+verify.length+' 道</span></div>'+questionRows(verify)+'</section><aside class="panel panel-pad"><h2 class="small-heading">什么时候可以放下这道题？</h2><p class="aside-note" style="margin-top:12px">独立做对，还要换个问法、隔段时间再试。系统把证据逐项记下，符合条件才进入这里。</p><div class="callout green">已掌握是一段时间内的证据结论。未来同技能抽检失误，会保留历史并重新安排复习。</div><p class="aside-note">暂停只是暂时不练，手动归档只是整理；它们都不会增加“已掌握”的数量。</p><p class="mini-rule">本 Demo 的“跨天两次 + 另一道变式 + 至少 7 天延迟”是待验证的产品策略，可随年级和学科调整。</p></aside></div>';}
function designView(){return heading('错题本的终点，是不再需要这道题。','围绕学生每一次真实作答，把收集、复习、迁移和掌握连在一起。','','THE PRODUCT, EXPLAINED')+'<div class="flow">'+['拍照保存','核对与打标','独立订正','间隔复习','变式与延迟验证','已掌握'].map((t,i)=>(i?icon('ChevronRight'):'')+'<span>'+t+'</span>').join('')+'</div><div class="spec-grid">'+[
 ['01','微信收来，网页接着学','已绑定的伙伴私聊接收题图，先保存原图，再到网页核对科目、题干与标签，进入同一复习计划。自动收题关闭时可附 /错题 单次收录。多题、模糊和同图重发分别处理，始终保留来源与学习历史。'],
 ['02','检索尊重要求，推荐解释原因','先按孩子、学段、科目和标签过滤。默认只召回复习中与待验证题，再考虑到期、反复错误、间隔与时间预算；用户明确找某知识点时，可提前练习。'],
 ['03','遗忘规律，决定何时再见','用实际复习历史调整间隔，不照搬固定天数。冷启动先用保守规则；积累记录后校准模型。记忆曲线不能直接代表应用能力，最难的题也不应一直霸占首位。'],
 ['04','一次做对，不直接关闭','辅助完成、看答案后的重做只算订正。跨天独立成功、另一道同技能变式与延迟验证共同支持关闭。抽检同技能再错就重开，学习轨迹始终保留。'],
 ['05','同类题验证，进阶题探索','每道变式关联母题，记录变化点、难度和目标技能。进阶若引入新技能，该技能的失败另记问题，不直接抹掉基础掌握；生成题需经过答案与课程范围校验。'],
 ['06','看延迟掌握，不追关闭数量','跟踪 7 天后独立同类题通过率、关闭后复发、复习负担与识别修正。对同一成熟队列评估，避免把“多收题、多点已掌握”误当作学习效果。']
 ].map(([n,t,d])=>'<section class="spec-card"><div class="number">'+n+'</div><h2>'+t+'</h2><p>'+d+'</p></section>').join('')+'</div><div class="callout">落地顺序：先复用现有拍题、标签与间隔调度，补齐关闭状态与证据；再连通母题与变式；最后用历史数据校准个性化推荐。当前项目的 resolved 与本轮 mastered 不能直接代表产品的“已掌握关闭”。</div><div class="sources"><strong>设计依据与边界</strong><br>间隔与保持时长相关：<a href="https://laplab.ucsd.edu/articles/Cepeda%20et%20al%202008_psychsci.pdf" target="_blank" rel="noopener">Cepeda 等，2008</a>；先提取再反馈：<a href="https://pubmed.ncbi.nlm.nih.gov/16507066/" target="_blank" rel="noopener">Roediger 与 Karpicke，2006</a>；应用题的迁移验证：<a href="https://pdf.retrievalpractice.org/transfer/McDaniel_etal_2013.pdf" target="_blank" rel="noopener">McDaniel 等，2013</a>；<a href="https://docs.ankiweb.net/deck-options.html#fsrs" target="_blank" rel="noopener">Anki FSRS 官方说明</a>。<br>研究支持设计方向；本 Demo 的权重、次数与 7 天阈值属于待验证的产品策略。页面不连接识图、生成或批改服务。</div>';}
function drawChart(){const canvas=$('#retention-chart');if(!canvas)return;const w=canvas.clientWidth,h=145,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const left=21,right=w-9,top=18,bottom=118;ctx.font='9px -apple-system, sans-serif';ctx.fillStyle='#9a9083';ctx.fillText('记忆保持（示意）',left,10);for(const frac of [0,.5,1]){const y=top+(bottom-top)*frac;ctx.strokeStyle='#eee8dd';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();}ctx.fillText('上次学习',left,bottom+18);ctx.fillText('今天',right-20,bottom+18);function curve(color,adaptive){ctx.strokeStyle=color;ctx.lineWidth=adaptive?2:1.5;ctx.setLineDash(adaptive?[]:[4,4]);ctx.beginPath();for(let i=0;i<=100;i++){const x=left+(right-left)*i/100;let retention=Math.exp(-i/38);if(adaptive){if(i>33)retention=Math.exp(-(i-33)/80)*.95;if(i>69)retention=Math.exp(-(i-69)/150)*.98;}const y=bottom-retention*(bottom-top);i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.stroke();}curve('#c3b5a2',false);curve('#ad532f',true);ctx.setLineDash([]);}
function render(){const names={today:'今日复习',library:'我的错题',inbox:'微信与拍照',mastery:'掌握档案',design:'设计说明'};$('#crumb-title').textContent=names[view];$('#profile-name').textContent=grade==='7'?'小禾的学习':'小满的学习';$('#role-toggle span').textContent=parent?'返回学生视角':'家长视角';$('#due-count').textContent=profiles().filter(q=>activeStatus(q)&&q.due<=TODAY).length;document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#main').innerHTML=({today:todayView,library:libraryView,inbox:inboxView,mastery:masteryView,design:designView}[view])();document.querySelectorAll('[data-icon]').forEach(n=>n.innerHTML=ICONS[n.dataset.icon]);if(view==='library')drawLibraryResults();if(view==='today')drawChart();}
function navigate(value){if(!['today','library','inbox','mastery','design'].includes(value))value='today';view=value;render();window.scrollTo({top:0,behavior:'instant'});}
function showModal(title,body,footer='',wide=false){if(!$('#modal-root').children.length){lastFocus=document.activeElement;}$('#modal-root').innerHTML='<div class="modal-scrim" id="modal-scrim"><section class="modal '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">'+title+'</h2><button class="icon-btn" id="close-modal" aria-label="关闭弹窗">'+icon('X')+'</button></header><div class="modal-body">'+body+'</div>'+(footer?'<footer class="modal-footer">'+footer+'</footer>':'')+'</section></div>';document.body.style.overflow='hidden';$('#close-modal').focus();}
function closeModal(){modal=null;session=null;$('#modal-root').innerHTML='';document.body.style.overflow='';if(lastFocus?.isConnected)lastFocus.focus();else $('#role-toggle').focus();}
function detail(id){const q=questions.find(q=>q.id===id);if(!q)return;modal={type:'detail',id};const historyHTML=q.attempts.slice().reverse().map(a=>'<div class="history-item"><strong>'+shortDate(a.date)+' · '+({original:'原题复习',similar:'同类变式',advanced:'进阶练习',spotcheck:'掌握抽检'}[a.type]||'练习')+'</strong>'+(!a.correct?'本次未做对':a.independent?'独立作答正确':'辅助完成 · 不累加掌握证据')+(a.newSkill?' · 新增技能单独记录':'')+'</div>').join('');showModal('这道题，学到哪一步了？','<div class="detail-grid"><div><div class="row between">'+statusBadge(q)+'<span class="small-text muted">'+q.subject+' · '+(q.grade==='7'?'七':'五')+'年级</span></div><h2 style="margin:14px 0">'+esc(q.title)+'</h2><div class="card-stem">'+esc(q.stem)+'</div>'+wxSourceLine(q,true)+'<label class="field">知识点<input id="edit-topic" value="'+esc(q.topic)+'"></label><label class="field">错因与自定义标签（逗号分隔）<input id="edit-tags" value="'+esc(q.tags.join(', '))+'"></label><button class="btn small" id="save-tags">'+icon('Tag')+'保存标签</button><div class="callout">'+esc(q.status==='closed'?'证据已通过，退出日常推荐。仍可低频抽检与重新学习。':q.status==='paused'?'暂时停下来，不代表已经掌握。恢复后按历史安排。':reason(q))+'</div></div><div><div class="detail-section"><h3>掌握证据</h3>'+rules(q)+'<p class="mini-rule">提示后完成与同日重做不计跨天证据；阈值为可调产品策略。</p></div><div class="detail-section"><h3>复习轨迹 · '+q.attempts.length+' 次</h3>'+(historyHTML||'<p class="aside-note">还没有复习记录，先独立试一次。</p>')+'</div></div></div>',(q.status==='closed'?'':'<button class="btn quiet" id="pause-question">'+icon(q.status==='paused'?'RotateCcw':'Pause')+(q.status==='paused'?'恢复复习':'暂停复习')+'</button>')+'<span class="spacer"></span>'+(activeStatus(q)?'<button class="btn" data-variant="'+q.id+'">'+icon('Sparkles')+'举一反三</button><button class="btn primary" data-practice="'+q.id+'">独立做一题 '+icon('ArrowRight')+'</button>':q.status==='closed'?'<button class="btn primary" data-spotcheck="'+q.id+'">抽检一下 '+icon('ArrowRight')+'</button>':''),true);}
function variant(id,type='similar'){const q=questions.find(q=>q.id===id);modal={type:'variant',id,variant:type};const v=q.variants[type];showModal('围绕这道错题，再走一步。','<div class="trace">'+icon('BookOpen')+'母题：'+esc(q.title)+'</div><div class="variant-options"><button class="variant-option '+(type==='similar'?'active':'')+'" data-variant-type="similar"><strong>同类巩固</strong><p>换情境或数值，验证同一种方法</p></button><button class="variant-option '+(type==='advanced'?'active':'')+'" data-variant-type="advanced"><strong>扩展进阶</strong><p>增加一步条件，探索更远一点</p></button></div><span class="tag rust">'+esc(v.topic)+'</span><div class="card-stem">'+esc(v.stem)+'</div><p class="aside-note">变化点：'+esc(v.dimension)+'</p><div class="callout '+(!v.newSkill?'green':'')+'">'+(v.newSkill?'这道进阶题包含新的知识点。新增技能失误会单独记录，不直接重开基础母题。':'目标技能与母题一致。独立通过可补充迁移证据；如果同技能再错，母题回到复习中。')+'</div><p class="notice-foot">预设变式示例，答案已人工核对。真实产品中，AI 生成需通过可解性、答案和课程范围校验，才进入正式练习。</p>','<p>只提供本题，先不显示答案。</p><span class="spacer"></span><button class="btn primary" id="start-variant">独立试试这道题 '+icon('ArrowRight')+'</button>');}
function startSession(ids,type='original'){const available=ids.map(id=>questions.find(q=>q.id===id)).filter(Boolean);if(!available.length){toast('当前没有可练习的题目');return;}session={ids:available.map(q=>q.id),index:0,startStatus:available[0].status,startDue:available[0].due,type,assisted:false,revealed:false,result:null,correct:0,completed:0,closed:0,startedAt:Date.now()};modal={type:'practice'};practiceView();}
function practiceView(){const s=session,q=questions.find(q=>q.id===s.ids[s.index]),variantType=['similar','advanced'].includes(s.type);const v=variantType?q.variants[s.type]:q;const label={original:s.startStatus==='verify'?'延迟验证':'独立复习',similar:'同类巩固',advanced:'扩展进阶',spotcheck:'已掌握抽检'}[s.type];const r=s.result;let content='<div class="row between"><span class="tag rust">'+label+' · '+q.subject+' · '+esc(v.topic)+'</span><span class="session-meta">第 '+(s.index+1)+' / '+s.ids.length+' 题</span></div><div class="session-progress"><span style="width:'+Math.round(s.index/s.ids.length*100)+'%"></span></div><h2>'+esc(q.title)+'</h2>'+(variantType?'<div class="trace">'+icon('Sparkles')+'母题关联 · '+esc(v.dimension)+'</div>':'')+(s.startDue>TODAY&&s.type==='original'&&!r?'<div class="callout">提前练习 · 原计划 '+shortDate(q.due)+' 复习。真实作答会记录，同日重复不会累加独立掌握次数。</div>':'')+'<div class="card-stem">'+esc(v.stem)+'</div>';
 if(!r){content+='<p class="aside-note">先不看答案，试着自己完成。需要帮助也没有关系。</p><div class="answer-area"><label for="answer" class="small-text">我的答案</label><input id="answer" autocomplete="off" placeholder="填写答案" aria-label="我的答案"><label class="field" style="margin:14px 0 0">我的思路（可选）<textarea id="working" placeholder="写一句为什么这样算，或在纸上完成后由家长/老师核对。"></textarea></label></div><div class="confidence"><span>这次做起来：</span><select id="confidence" aria-label="作答感受"><option value="normal">比较顺利</option><option value="hard">做对也有点吃力</option><option value="guess">我有点不确定</option></select><span class="spacer"></span><button class="text-btn" id="show-hint">'+icon('Lightbulb')+'给我一点提示</button><button class="text-btn" id="show-answer">看解析</button></div><div id="help-area">'+(s.revealed?'<div class="reveal">参考答案：'+esc(v.answer)+'<br>'+esc(v.solution)+'<br>本次已看解析，之后做对记为订正，不作为独立掌握证据。</div>':s.assisted?'<div class="reveal">'+esc(variantType?'先找出与母题相同的目标技能，再检查题目新增了哪些条件。':q.hint)+'<br>本次使用提示，做对将记为辅助完成。</div>':'')+'</div><p class="notice-foot">演示批改仅核对最终答案，不能验证完整解题过程；真实主观题需过程批改或人工确认。小学家长核对结果不能代替孩子作答。</p>';
 }else{content+='<div class="result-box '+(!r.correct?'fail':'')+'"><h3>'+(!r.correct?'这次还没做对，我们再想一步。':!r.independent?'这次完成了，再留一次独立尝试。':r.newlyClosed?'这道错题，可以放心放下了。':'独立做对，记下这一步进步。')+'</h3><p>'+esc(r.message)+'</p></div><div class="reveal">参考答案：'+esc(v.answer)+'<br>'+esc(v.solution)+'</div><h3>这道题的掌握证据</h3>'+rules(q)+'<div class="callout '+(q.status==='closed'?'green':'')+'">'+(q.status==='closed'?'已进入掌握档案，退出日常推荐。下次低频抽检：'+shortDate(q.due)+'。':r.newSkill&&!r.correct?'新增技能需要单独练习，基础母题状态保留。':q.status==='paused'?'本题仍处于暂停状态。':'下一次建议：'+shortDate(q.due)+' · '+(!r.independent?'留一点间隔，再独立完成。':!r.correct?'先订正，再安排一次新的独立尝试。':'根据本次表现继续安排间隔。'))+'</div>';}
showModal(label,content,r?'<button class="btn quiet" id="practice-detail">查看学习轨迹</button><span class="spacer"></span>'+ (s.type==='original'?'<button class="btn" data-variant="'+q.id+'">再练同类题</button>':'')+'<button class="btn primary" id="next-question">'+(s.index+1<s.ids.length?'下一道题':'完成本组')+' '+icon('ArrowRight')+'</button>':'<p>看过提示或解析，会如实记录。</p><span class="spacer"></span><button class="btn primary" id="submit-answer">提交答案 '+icon('ArrowRight')+'</button>');}
function normalize(value){return String(value).trim().toLowerCase().replace(/[°。\s]/g,'').replace('−','-');}
function submitAnswer(){if(!session||session.result)return;const input=$('#answer').value.trim();if(!input){toast('先写下自己的答案，再提交');$('#answer').focus();return;}const s=session,q=questions.find(q=>q.id===s.ids[s.index]),variantType=['similar','advanced'].includes(s.type),v=variantType?q.variants[s.type]:q;const correct=normalize(input)===normalize(v.answer),newSkill=!!v.newSkill,priorExposure=(q.exposures||[]).some(a=>a.date===TODAY&&(!a.newSkill||a.type===s.type))||q.attempts.some(a=>a.date===TODAY&&((a.assisted||a.revealed)&&!a.newSkill||a.feedbackShown&&(a.type===s.type||['original','spotcheck'].includes(a.type)&&['original','spotcheck'].includes(s.type)))),independent=!s.assisted&&!s.revealed&&!priorExposure&&$('#confidence').value!=='guess';const before=q.status;const a=history(TODAY,s.type,correct,independent,{newSkill,answer:input,working:$('#working').value,confidence:$('#confidence').value,assisted:s.assisted,revealed:s.revealed,feedbackShown:true,elapsedSeconds:Math.round((Date.now()-s.startedAt)/1000)});q.attempts.push(a);
let newlyClosed=false,message='';if(newSkill){message=correct?'新的挑战完成了。这次只补充新增技能记录，基础母题的关闭条件仍单独验证。':'这次的新增技能还需练习。已记录为扩展技能缺口，基础母题不会因此自动重开。';}
else if(!correct){q.status='open';q.lapses++;q.last=TODAY;q.stability=Math.max(1,q.stability*.6);q.due=datePlus(1);message=before==='closed'?'抽检发现同技能问题，已重新打开这道错题。此前的学习与关闭记录继续保留。':'已记录本次失误。先看清错因，明天再独立试一次；这次不累加掌握证据。';}
else if(!independent){if(q.status!=='closed')q.due=datePlus(1);message='本次记录为'+(s.revealed||priorExposure?'同日接触答案或提示后的订正':s.assisted?'提示后的辅助完成':'正确但不确定')+'，不新增独立掌握证据。'+(before==='closed'?'此前已验证的掌握记录保留。':'明天再独立试一次。');}
else{q.last=TODAY;q.stability=Math.min(45,q.stability*1.7);const currentEvidence=evidence(q);if(before==='closed'||currentEvidence.ready){q.closureEvidence=currentEvidence;q.status='closed';if(before!=='closed')q.closedAt=TODAY;q.due=datePlus(21);newlyClosed=before!=='closed';message=before==='closed'?'本次抽检通过，掌握证据继续保留。':'跨天独立复习、同技能变式与延迟验证均已通过。这道题已进入掌握档案。';}else{q.status='verify';q.due=datePlus(7);message='这次独立做对了。'+(!evidence(q).transfer?'还需要一道同技能变式，':'')+'再隔一段时间验证，才判断是否已掌握。';}}
s.completed++;if(correct&&independent)s.correct++;if(newlyClosed)s.closed++;s.result={correct,independent,newSkill,newlyClosed,message};render();practiceView();}
function nextQuestion(){if(!session?.result)return;if(session.index+1<session.ids.length){session.index++;const next=questions.find(q=>q.id===session.ids[session.index]);session.startStatus=next.status;session.startDue=next.due;session.assisted=false;session.revealed=false;session.result=null;session.startedAt=Date.now();practiceView();return;}const s=session;modal={type:'summary'};showModal('这一组，已经认真走完。','<div class="session-summary">'+icon('ShieldCheck')+'<h2>每一次独立思考，都在积累。</h2><p class="aside-note" style="margin-top:9px">做对的记下，没做对的留给下一次。</p><div class="summary-numbers"><div><strong>'+s.completed+'</strong><span>完成题目</span></div><div><strong>'+s.correct+'</strong><span>独立做对</span></div><div><strong>'+s.closed+'</strong><span>新掌握关闭</span></div></div><div class="callout" style="text-align:left">辅助完成与订正也会保留记录。没有达到关闭条件的题目，会按这次表现安排下一次复习。</div></div>','<button class="btn" id="summary-close">回到今日复习</button><span class="spacer"></span><button class="btn primary" id="summary-mastery">查看掌握档案 '+icon('ArrowRight')+'</button>');}
function addIntake(){const stem=$('#intake-stem').value.trim(),topic=$('#intake-topic').value.trim(),sub=$('#intake-subject').value;if(!stem||!topic){toast('请补充完整题干和知识点');return;}if(!$('#intake-confirm').checked){toast('请先核对题干、科目与知识点，再勾选确认');$('#intake-confirm').focus();return;}const template=structuredClone(INITIAL.find(q=>q.id===(grade==='5'?'p1':'m2')));const standardStem=grade==='5'?'计算：1/3 + 1/6 = ?（请用分数填写）':'解方程：2x + 3 = 11，x = ?';const answerKnown=stem===standardStem&&topic===(grade==='5'?'异分母分数加法':'一元一次方程')&&sub==='数学';if(!answerKnown){toast('修改后的题目已核对，但演示无法真实批改；请保留示例题干体验复习');return;}const existing=questions.find(q=>q.grade===grade&&q.stem===stem);if(existing){toast('发现相同题干，已定位已有错题，保留复习历史');detail(existing.id);return;}questions.push({...template,id:'new-'+Date.now(),title:topic+' · 新收录错题',stem,topic,subject:sub,tags:$('#intake-tags').value.split(/[,，]/).map(s=>s.trim()).filter(Boolean),status:'open',due:TODAY,last:TODAY,stability:1,lapses:0,created:TODAY,attempts:[],answer:grade==='5'?'1/2':'4',hint:wxDrafts(grade,'clear')[0].hint,variants:wxDrafts(grade,'clear')[0].variants||template.variants,solution:grade==='5'?'1/3 = 2/6，和为 3/6 = 1/2。':'2x = 8，所以 x = 4。',source:uploadFile?'本地照片预览':'预设示例'});subject='全部';statusFilter='active';search='';tagFilter='全部';location.hash='library';navigate('library');toast('已收录并加入复习，首次独立尝试将成为新记录');}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(b?.disabled)return;if(b?.dataset.go){location.hash=b.dataset.go;return;}if(b?.dataset.subject){subject=b.dataset.subject;render();return;}if(b?.dataset.budget){budget=Number(b.dataset.budget);render();return;}if(b?.dataset.status){statusFilter=b.dataset.status;render();return;}if(b?.dataset.detail){detail(b.dataset.detail);return;}if(b?.dataset.practice){startSession([b.dataset.practice]);return;}if(b?.dataset.spotcheck){startSession([b.dataset.spotcheck],'spotcheck');return;}if(b?.dataset.variant){variant(b.dataset.variant);return;}if(b?.dataset.variantType){variant(modal.id,b.dataset.variantType);return;}if(b?.dataset.intakeScenario){uploadScenario=b.dataset.intakeScenario;intakeForm();return;}
switch(b?.id){
case 'start-plan':startSession(plan().items.map(q=>q.id));break;
case 'role-toggle':parent=!parent;render();toast(parent?'已切换为家长视角':'已回到学生视角');break;
case 'reset':resetWxDemo();questions=structuredClone(INITIAL);for(const q of questions){if(q.status==='closed')q.closureEvidence=structuredClone(evidence(q));}subject='全部';statusFilter='active';tagFilter='全部';search='';budget=15;parent=false;closeModal();render();toast('演示记录已重置');break;
case 'close-modal':closeModal();break;
case 'clear-filters':subject='全部';statusFilter='active';tagFilter='全部';search='';render();break;
case 'practice-results':startSession(libraryItems().filter(activeStatus).map(q=>q.id));break;
case 'save-tags':{const q=questions.find(q=>q.id===modal.id),topic=$('#edit-topic').value.trim();if(!topic){toast('知识点不能为空');break;}q.topic=topic;q.tags=[...new Set($('#edit-tags').value.split(/[,，]/).map(t=>t.trim()).filter(Boolean))];render();detail(q.id);toast('标签已保存，可在错题库按标签找题');break;}
case 'pause-question':{const q=questions.find(q=>q.id===modal.id);if(q.status==='closed'){toast('已掌握题无需暂停，可直接抽检');break;}q.status=q.status==='paused'?'open':'paused';render();detail(q.id);toast(q.status==='paused'?'已暂停，不计为掌握':'已恢复，继续按历史安排');break;}
case 'start-variant':startSession([modal.id],modal.variant);break;
case 'show-hint':case 'show-answer':{const draft=$('#answer').value,working=$('#working').value,confidence=$('#confidence').value;const exposedQuestion=questions.find(q=>q.id===session.ids[session.index]);(exposedQuestion.exposures??=[]).push({date:TODAY,type:session.type,newSkill:!!exposedQuestion.variants[session.type]?.newSkill,kind:b.id==='show-answer'?'answer':'hint'});if(b.id==='show-answer'){session.revealed=true;session.assisted=true;}else session.assisted=true;practiceView();$('#answer').value=draft;$('#working').value=working;$('#confidence').value=confidence;$('#help-area').scrollIntoView({block:'nearest'});break;}
case 'submit-answer':submitAnswer();break;
case 'next-question':nextQuestion();break;
case 'practice-detail':{const id=session.ids[session.index];session=null;detail(id);break;}
case 'summary-close':closeModal();location.hash='today';navigate('today');break;
case 'summary-mastery':closeModal();location.hash='mastery';navigate('mastery');break;
case 'choose-photo':$('#photo-file').click();break;
case 'sample-photo':uploadScenario='clear';intakeForm();toast('已载入预设题干，请核对后加入');break;
case 'add-intake':addIntake();break;
case 'merge-duplicate':toast('已合并示例来源，原有标签与复习历史保留');detail(grade==='5'?'p1':'m2');break;
}
if(event.target.id==='modal-scrim')closeModal();});
document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;drawLibraryResults();}});
document.addEventListener('change',event=>{if(event.target.id==='learner'){grade=event.target.value;subject='全部';statusFilter='active';search='';tagFilter='全部';closeModal();render();toast(grade==='5'?'已切换到五年级示例，可由家长协助核对':'已切换到七年级示例');}if(event.target.id==='tag-filter'){tagFilter=event.target.value;drawLibraryResults();}if(event.target.id==='sort'){sort=event.target.value;drawLibraryResults();}if(event.target.id==='photo-file'){const f=event.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>20*1024*1024){toast('请选择 20 MB 以内的 JPG、PNG 或 WebP 图片');return;}if(localImage)URL.revokeObjectURL(localImage);localImage=URL.createObjectURL(f);uploadFile=f;$('#photo-preview').innerHTML='<img class="local-image" src="'+localImage+'" alt="所选错题照片的本地预览">';uploadScenario='clear';intakeForm();toast('照片仅在本机预览，下方为预设识别示例');}});
document.addEventListener('keydown',event=>{if(!$('#modal-root').children.length)return;if(event.key==='Escape'){closeModal();event.preventDefault();return;}if(event.key==='Tab'){const nodes=[...document.querySelector('.modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(n=>n.offsetParent!==null);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
window.addEventListener('resize',()=>{if(view==='today')drawChart();});
for(const q of questions){if(q.status==='closed')q.closureEvidence=structuredClone(evidence(q));}
navigate(location.hash.slice(1)||'today');
